def transform(value):
    if not isinstance(value,list): return []
    out=[]; seen=set()
    for group in value:
        if not isinstance(group,list): continue
        for tag in group:
            if not isinstance(tag,str): continue
            t=tag.strip().lower()
            if t and t not in seen: seen.add(t); out.append(t)
    return out
